site_pages.custom_css:
.tkd-page-scope {
      font-family: 'Be Vietnam Pro', 'Inter', system-ui, -apple-system, sans-serif;
      -webkit-text-size-adjust: 100%;
      text-size-adjust: 100%;
      background-color: #f8fafc;
      color: #0f172a;
      overflow-y: visible;
      height: auto;
    }


    .tkd-page-scope .math-font {
      font-family: 'Noto Serif', serif;
    }


    .tkd-page-scope .num-font {
      font-family: 'Roboto Mono', monospace;
      font-variant-numeric: tabular-nums;
    }


    
    .tkd-page-scope .table-container::-webkit-scrollbar {
      height: 3px;
    }

    .tkd-page-scope .table-container::-webkit-scrollbar-track {
      background: #f1f5f9;
    }

    .tkd-page-scope .table-container::-webkit-scrollbar-thumb {
      background: #cbd5e1;
      border-radius: 9999px;
    }


    
    .tkd-page-scope .marquee-track {
      display: inline-block;
      white-space: nowrap;
      animation: marquee 16s linear infinite;
    }

    @keyframes marquee {
      0% { transform: translateX(100%); }
      100% { transform: translateX(-100%); }
    }


    
    .tkd-page-scope .vertical-marquee {
      position: absolute;
      width: 100%;
      display: flex;
      flex-direction: column;
      gap: 10px;
      animation: verticalScroll 20s linear infinite;
    }

    .tkd-page-scope .vertical-marquee:hover {
      animation-play-state: paused;
    }

    @keyframes verticalScroll {
      0% { transform: translateY(100%); }
      100% { transform: translateY(-100%); }
    }


    
    .tkd-page-scope .smooth-blink {
      animation: smoothBlink 2.5s infinite ease-in-out;
    }

    @keyframes smoothBlink {
      0%, 100% { opacity: 0.3; color: #64748b; }
      50% { opacity: 1; color: #C65B69; }
    }

