// 4. Lịch Việt Nam Âm - Dương
    const TIMEZONE = 7;
    function INT(d){ return Math.floor(d); }
    function getJd(dd, mm, yy){
      let a = INT((14 - mm) / 12), y = yy + 4800 - a, m = mm + 12 * a - 3;
      let jd = dd + INT((153 * m + 2) / 5) + 365 * y + INT(y / 4) - INT(y / 100) + INT(y / 400) - 32045;
      if (jd < 2299161) jd = dd + INT((153 * m + 2) / 5) + 365 * y + INT(y / 4) - 32083;
      return jd;
    }
    function getNewMoonDay(k, tz){
      let T = k / 1236.85, T2 = T * T, T3 = T2 * T, dr = Math.PI / 180;
      let Jd1 = 2415020.75933 + 29.53058868 * k + 0.0001178 * T2 - 0.000000155 * T3;
      Jd1 += 0.00033 * Math.sin((166.56 + 132.87 * T - 0.009173 * T2) * dr);
      let M = 359.2242 + 29.10535608 * k - 0.0000333 * T2 - 0.00000347 * T3;
      let Mpr = 306.0253 + 385.81691806 * k + 0.0107306 * T2 + 0.00001236 * T3;
      let F = 21.2964 + 390.67050646 * k - 0.0016528 * T2 - 0.00000239 * T3;
      let C1 = (0.1734 - 0.000393 * T) * Math.sin(M * dr) + 0.0021 * Math.sin(2 * dr * M);
      C1 = C1 - 0.4068 * Math.sin(Mpr * dr) + 0.0161 * Math.sin(dr * 2 * Mpr) - 0.0004 * Math.sin(dr * 3 * Mpr)
           + 0.0104 * Math.sin(dr * 2 * F) - 0.0051 * Math.sin(dr * (M + Mpr)) - 0.0074 * Math.sin(dr * (M - Mpr))
           + 0.0004 * Math.sin(dr * (2 * F + M)) - 0.0004 * Math.sin(dr * (2 * F - M)) - 0.0006 * Math.sin(dr * (2 * F + Mpr))
           + 0.0010 * Math.sin(dr * (2 * F - Mpr)) + 0.0005 * Math.sin(dr * (2 * Mpr + M));
      let deltat = (T < -11) ? (0.001 + 0.000839 * T + 0.0002261 * T2 - 0.00000845 * T3 - 0.000000081 * T * T3)
                             : (-0.000278 + 0.000265 * T + 0.000262 * T2);
      let JdNew = Jd1 + C1 - deltat;
      return INT(JdNew + 0.5 + tz / 24);
    }
    function getSunLongitude(jdn, tz){
      let T = (jdn - 2451545.5 - tz / 24) / 36525, T2 = T * T, dr = Math.PI / 180;
      let M = 357.52910 + 35999.05030 * T - 0.0001559 * T2 - 0.00000048 * T * T2;
      let L0 = 280.46645 + 36000.76983 * T + 0.0003032 * T2;
      let DL = (1.914600 - 0.004817 * T - 0.000014 * T2) * Math.sin(dr * M)
             + (0.019993 - 0.000101 * T) * Math.sin(dr * 2 * M) + 0.000290 * Math.sin(dr * 3 * M);
      let L = (L0 + DL) * dr; L = L - Math.PI * 2 * (INT(L / (Math.PI * 2)));
      return INT(L / Math.PI * 6);
    }
    function getLunarMonth11(yy, tz){
      let off = getJd(31, 12, yy) - 2415021, k = INT(off / 29.530588853);
      let nm = getNewMoonDay(k, tz), sunLong = getSunLongitude(nm, tz);
      if (sunLong >= 9) nm = getNewMoonDay(k - 1, tz);
      return nm;
    }
    function getLeapMonthOffset(a11, tz){
      let k = INT((a11 - 2415021.076998695) / 29.530588853 + 0.5), last = 0, i = 1;
      let arc = getSunLongitude(getNewMoonDay(k + i, tz), tz);
      do { last = arc; i++; arc = getSunLongitude(getNewMoonDay(k + i, tz), tz); } while (arc != last && i < 14);
      return i - 1;
    }
    function convertSolar2Lunar(dd, mm, yy, tz){
      let dayNumber = getJd(dd, mm, yy);
      let k = INT((dayNumber - 2415021.076998695) / 29.530588853);
      let monthStart = getNewMoonDay(k + 1, tz);
      if (monthStart > dayNumber) monthStart = getNewMoonDay(k, tz);
      let a11 = getLunarMonth11(yy, tz), b11 = a11, lunarYear;
      if (a11 >= monthStart){ lunarYear = yy; a11 = getLunarMonth11(yy - 1, tz); }
      else { lunarYear = yy + 1; b11 = getLunarMonth11(yy + 1, tz); }
      let lunarDay = dayNumber - monthStart + 1;
      let diff = INT((monthStart - a11) / 29), lunarLeap = 0, lunarMonth = diff + 11;
      if (b11 - a11 > 365){
        let leapDiff = getLeapMonthOffset(a11, tz);
        if (diff >= leapDiff){ lunarMonth = diff + 10; if (diff == leapDiff) lunarLeap = 1; }
      }
      if (lunarMonth > 12) lunarMonth -= 12;
      if (lunarMonth >= 11 && diff < 4) lunarYear -= 1;
      return [lunarDay, lunarMonth, lunarYear, lunarLeap];
    }
    const weekdays = ["Chủ Nhật", "Thứ Hai", "Thứ Ba", "Thứ Tư", "Thứ Năm", "Thứ Sáu", "Thứ Bảy"];
    const can = ["Giáp", "Ất", "Bính", "Đinh", "Mậu", "Kỷ", "Canh", "Tân", "Nhâm", "Quý"];
    const chi = ["Tý", "Sửu", "Dần", "Mão", "Thìn", "Tỵ", "Ngọ", "Mùi", "Thân", "Dậu", "Tuất", "Hợi"];

    let currentDate = new Date();
    function updateCalendar(){
      const header = document.getElementById('header');
      const dayNumber = document.getElementById('dayNumber');
      const dayName = document.getElementById('dayName');
      const lunarDay = document.getElementById('lunarDay');
      const lunarYear = document.getElementById('lunarYear');
      const dateInput = document.getElementById('dateInput');

      const d = currentDate.getDate(), m = currentDate.getMonth() + 1, y = currentDate.getFullYear();
      header.textContent = `Tháng ${m} - ${y}`;
      dayNumber.textContent = d;
      dayName.textContent = weekdays[currentDate.getDay()];

      const [lDay, lMonth, lYear, lLeap] = convertSolar2Lunar(d, m, y, TIMEZONE);
      lunarDay.textContent = `${lDay}/${lMonth}${lLeap ? ' (Nhuận)' : ''}`;

      const canIndex = (lYear + 6) % 10, chiIndex = (lYear + 8) % 12;
      lunarYear.innerHTML = `Năm ${can[canIndex]} ${chi[chiIndex]}`;

      dateInput.value = currentDate.toISOString().split('T')[0];
    }
    function changeDate(days){ currentDate.setDate(currentDate.getDate() + days); updateCalendar(); }
    document.getElementById('dateInput').addEventListener('change', e => { currentDate = new Date(e.target.value); updateCalendar(); });
    updateCalendar();

    // 5. Ngày Lễ Hôm Nay
    const holidays = {
      "1/1":   "Ngày 1/1: 🎉 Chúc mừng Năm Mới (Tết Dương Lịch)!",
      "14/2":  "Ngày 14/2: ❤️ Ngày Lễ Tình Nhân (Valentine)!",
      "8/3":   "Ngày 8/3: 🌹 Ngày Quốc tế Phụ nữ!",
      "26/3":  "Ngày 26/3: 🔥 Ngày Thành lập Đoàn TNCS Hồ Chí Minh!",
      "30/4":  "Ngày 30/4: 🎆 Ngày Giải phóng miền Nam, Thống nhất Đất nước!",
      "1/5":   "Ngày 1/5: 🛠️ Ngày Quốc tế Lao động!",
      "19/5":  "Ngày 19/5: ⛰️ Ngày sinh Chủ tịch Hồ Chí Minh!",
      "1/6":   "Ngày 1/6: 🧸 Ngày Quốc tế Thiếu nhi!",
      "27/7":  "Ngày 27/7: 🕯️ Ngày Thương binh - Liệt sĩ Việt Nam!",
      "19/8":  "Ngày 19/8: 👮 Ngày Cách mạng Tháng Tám thành công!",
      "2/9":   "Ngày 2/9: 🇻🇳 Ngày Quốc khánh Nước CHXHCN Việt Nam!",
      "10/10": "Ngày 10/10: 🏛️ Ngày Giải phóng Thủ đô!",
      "20/10": "Ngày 20/10: 🌸 Ngày Phụ nữ Việt Nam!",
      "20/11": "Ngày 20/11: 👨‍🏫 Ngày Nhà giáo Việt Nam!",
      "22/12": "Ngày 22/12: 🎖️ Ngày Thành lập Quân đội Nhân dân Việt Nam!",
      "25/12": "Ngày 25/12: 🎄 Ngày Lễ Giáng Sinh (Noel)!"
    };
    function updateHolidayToday() {
      const today = new Date(); const d = today.getDate(); const m = today.getMonth() + 1; const key = `${d}/${m}`;
      const el = document.getElementById('holiday-today');
      const text = holidays[key] || "Hôm nay không có ngày lễ lớn nào!";
      const icon = /🎉|❤️|🌹|🔥|🎆|🛠️|⛰️|🧸|🕯️|👮|🇻🇳|🏛️|🌸|👨‍🏫|🎖️|🎄/.exec(text)?.[0] || "📅";
      el.innerHTML = `<span>${icon}</span><span>${text}</span>`;
    }
    updateHolidayToday();

        // 6. Vòng quay may mắn (3 giây mượt mà)
    function startLottery(){
      const quantity = parseInt(document.getElementById('quantity').value);
      const numbersDiv = document.getElementById('numbers');
      const resultDiv = document.getElementById('luck-result');
      if (isNaN(quantity) || quantity < 3){ alert("Vui lòng nhập số lượng hợp lệ (≥ 3)."); return; }

      const pool = Array.from({length: quantity}, (_, i) => i + 1);
      numbersDiv.textContent = "Đang quay số..."; resultDiv.textContent = "";

      const roller = setInterval(() => {
        const temp = []; for(let i = 0; i < 3; i++){ temp.push(1 + Math.floor(Math.random() * quantity)); }
        numbersDiv.textContent = temp.join(', ');
      }, 80);

      setTimeout(() => {
        clearInterval(roller);
        const picked = new Set();
        while(picked.size < 3){ picked.add(pool[Math.floor(Math.random() * pool.length)]); }
        const finalNumbers = [...picked];
        numbersDiv.textContent = finalNumbers.join(', ');
        resultDiv.innerHTML = `<strong>Chúc mừng những số may mắn:</strong><br>• ${finalNumbers.join(', ')}`;
      }, 3000);
    }

