// 1. Cập nhật năm hiện hành
    document.addEventListener("DOMContentLoaded", function() {
      const year = new Date().getFullYear();
      const currentYearEl = document.getElementById("currentYear");
      const footerYearEl = document.getElementById("footerYear");
      if (currentYearEl) currentYearEl.textContent = year;
      if (footerYearEl) footerYearEl.textContent = year;
      
    });

    // 2. Cơ sở dữ liệu liên kết đề tài
    const dataLinks = {
      "00": "https://docs.google.com/document/d/1YXNO898_BBonDMTRmFyhrDTRYqHiIXmbvZThOif42gM/edit?usp=drive_link",
      "01": "https://docs.google.com/document/d/19y1iS9SzS3b88z4q8c4xZqhq0f7FrOIpvlHak8gkEjQ/edit?usp=drive_link",
      "A040201": "https://docs.google.com/document/d/1ujLI3XeDZntrg9wwJEL1NBpj1GcWOGFVrIrq9-_kANg/edit?usp=drive_link",
      "B040202": "https://docs.google.com/document/d/11U5Yue-dDprhsWHsakXi6-i9Ik-A5bfWfDt_YWTUTwg/edit?usp=drive_link",
      "C040203": "https://docs.google.com/document/d/1H4Or-zZD5eGXQ_Dfpu5yXw1NASFRla6ssSWucoEHhOw/edit?usp=drive_link",
      "D040204": "https://docs.google.com/document/d/1R6QK02dVVQtiN6sCn3RR2GuXrVzgHhna2TE1uWpOsWk/edit?usp=drive_link",
      "E040205": "https://docs.google.com/document/d/1mBKg7oDxu8jqEFCIGZT5x7msztTdm-D8iww_0y7GNeg/edit?usp=drive_link",
      "F040206": "https://docs.google.com/document/d/19Ac2fEsAiUK1y5o4VFCniThLjHk_AU8FpuLWSqBXdeY/edit?usp=drive_link",
      "G040207": "https://docs.google.com/document/d/1KKYhEmhaCMY0GwLkJK2VrrSHZdMQcdcMi8L7yDN0Fi4/edit?usp=drive_link",
      "H040208": "https://docs.google.com/document/d/1saE-MXec0PMcbemLZTeuAt54esLyDZ1L54kFUNB4NlE/edit?usp=drive_link",
      "I040209": "https://docs.google.com/document/d/1SP712K7AF3u-qs42U57wUy6ceodYSNHzmbSo7p2BlEc/edit?usp=drive_link",
      "J040210": "https://docs.google.com/document/d/1T1zsBMP8tCgtzKaAA-LxA7mwS-84iVaa8Hw2EfT3yoY/edit?usp=drive_link",
