      "S040219": "https://docs.google.com/document/d/1ZRz4aCq0MgfR4x4Lgwi6OUIUZgGItp9iyVkx5mrYxWg/edit?usp=drive_link",
      "T040220": "https://docs.google.com/document/d/1ppYgrSMWxQpdfOlAzkN8DRgjp0wKdLs3ko2fBtXiriI/edit?usp=drive_link"
    };

    // Điền nhanh mã từ bảng vào ô tìm kiếm
    function quickFill(code) {
      const input = document.getElementById('student-code');
      input.value = code;
      checkCode();
    }

    // Xử lý kiểm tra mã và hiển thị kết quả
    function checkCode() {
      const input = document.getElementById('student-code');
      const val = input.value.trim().toUpperCase();
      const resultDiv = document.getElementById('result');

      resultDiv.classList.remove('hidden');

      if (!val) {
        resultDiv.className = "bg-rose-50 border-l-3 border-rose-600 p-2.5 rounded-r-lg text-[10px] sm:text-xs text-rose-900";
        resultDiv.innerHTML = "<strong>⚠️ Thông báo:</strong> Vui lòng nhập mã số đề tài hoặc mã tài liệu để tra cứu.";
        return;
      }

      if (dataLinks.hasOwnProperty(val)) {
        let labelText = "Mã hợp lệ! Tải tài liệu hướng dẫn đề tài:";
        if (val === "00") labelText = "Mã hợp lệ! Tải về Đề cương chi tiết học phần:";
        else if (val === "01") labelText = "Mã hợp lệ! Tải về Mẫu bảng điểm & Phiếu chấm thực tập:";

        resultDiv.className = "bg-emerald-50 border-l-3 border-emerald-600 p-2.5 rounded-r-lg text-[10px] sm:text-xs text-emerald-950 flex flex-col sm:flex-row sm:items-center justify-between gap-2";
        resultDiv.innerHTML = `
          <div>
            <h4 class="font-bold uppercase tracking-tight text-emerald-900">${labelText}</h4>
            <p class="text-emerald-800 font-medium">Mã tra cứu: <span class="num-font font-bold text-[#A83245]">${val}</span></p>
          </div>
          <a href="${dataLinks[val]}" target="_blank" rel="noopener"
             class="inline-flex items-center justify-center gap-1.5 bg-emerald-700 hover:bg-emerald-800 text-white font-bold px-3 py-1.5 rounded-lg shadow-xs transition-colors shrink-0 text-[10px] sm:text-xs">
            <svg class="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4" />
            </svg>
            Tải Tài Liệu Về ↗
          </a>
        `;
      } else {
        resultDiv.className = "bg-rose-50 border-l-3 border-rose-600 p-2.5 rounded-r-lg text-[10px] sm:text-xs text-rose-900 space-y-1";
        resultDiv.innerHTML = `
          <h4 class="font-bold uppercase tracking-tight text-rose-900">Mã Số Không Hợp Lệ Hoặc Chưa Được Kích Hoạt</h4>
          <p class="font-medium">Hệ thống không tìm thấy tài liệu tương ứng với mã <strong class="num-font font-bold text-slate-900">${val}</strong>.</p>
          <p class="text-[9.5px] text-rose-800">Vui lòng kiểm tra lại mã số hoặc liên hệ trực tiếp Giảng viên hướng dẫn qua email <strong class="num-font">phuongntt@kthcm.edu.vn</strong> để được hỗ trợ.</p>
        `;
      }
    }

    // Lắng nghe phím Enter trên ô nhập liệu
    document.getElementById('student-code').addEventListener('keypress', function (e) {
      if (e.key === 'Enter') {
        checkCode();
      }
    });

