site_pages.custom_js:
(function() {
  const form = document.getElementById('surveyForm');
  if (!form) return;
  form.addEventListener('change', function(e) {
    const t = e.target;
    if (t && t.type === 'radio' && t.name) {
      document.querySelectorAll('input[type="radio"][name="' + t.name + '"][value="' + t.value + '"]').forEach(function(r) {
        r.checked = true;
      });
    }
  });

  form.addEventListener('submit', async function(e) {
    e.preventDefault();
    const formData = new FormData(form);
    const answers = {};
    for (const [key, val] of formData.entries()) {
      answers[key] = val;
    }

    const studentName = (answers.student_name || answers.fullname || 'Sinh viên HCE').trim();
    const studentId = (answers.student_id || answers.mssv || '').trim();
    const className = (answers.class_name || answers.class || 'NCKH SV').trim();

    try {
      await fetch('/api/surveys', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          survey_type: 'nckh',
          student_name: studentName,
          student_id: studentId,
          class_name: className,
          answers: answers,
        }),
      });
    } catch (err) {
      console.error('Error saving survey:', err);
    }

    const keys = Object.keys(answers);
    const header = 'Họ tên,MSSV,Lớp,Thời gian,' + keys.join(',') + '\n';
    const esc = (v) => '"' + String(v ?? '').replace(/"/g, '""') + '"';
    const row = [esc(studentName), esc(studentId), esc(className), esc(new Date().toLocaleString('vi-VN')), ...keys.map(k => esc(answers[k]))].join(',');
    const blob = new Blob(['\uFEFF' + header + row], { type: 'text/csv;charset=utf-8;' });
    const dlUrl = URL.createObjectURL(blob);

    const modalHtml = `
      <div id="surveySuccessModal" style="position:fixed;inset:0;background:rgba(15,23,42,0.6);backdrop-filter:blur(4px);z-index:9999;display:flex;align-items:center;justify-content:center;padding:16px;">
        <div style="background:#fff;border-radius:24px;max-width:480px;width:100%;padding:28px;text-align:center;box-shadow:0 25px 50px -12px rgba(0,0,0,0.25);">
          <div style="width:56px;height:56px;border-radius:50%;background:#dcfce7;color:#16a34a;font-size:28px;display:flex;align-items:center;justify-content:center;margin:0 auto 16px;">✓</div>
          <h3 style="font-size:18px;font-weight:800;color:#0f172a;margin:0 0 8px;">Gửi Khảo Sát NCKH Thành Công!</h3>
          <p style="font-size:13px;color:#475569;margin:0 0 20px;line-height:1.5;">Cảm ơn bạn đã tham gia đóng góp dữ liệu cho đề tài nghiên cứu khoa học. Dữ liệu của bạn đã được ghi nhận bảo mật trên hệ thống Cloudflare D1.</p>
          <div style="display:flex;flex-direction:column;gap:10px;">
            <a href="${dlUrl}" download="KhaoSat_NCKH_${Date.now()}.csv" style="display:inline-flex;align-items:center;justify-content:center;gap:8px;padding:12px 20px;border-radius:12px;background:#059669;color:#fff;font-weight:700;font-size:13px;text-decoration:none;">
              📥 Tải Về Kết Quả (File Excel .CSV Cho SPSS)
            </a>
            <button id="closeSurveyModalBtn" type="button" style="padding:10px 20px;border-radius:12px;border:1px solid #cbd5e1;background:#fff;color:#334155;font-weight:700;font-size:13px;cursor:pointer;">
              Đóng & Hoàn Tất
            </button>
          </div>
        </div>
      </div>
    `;
    const container = document.createElement('div');
    container.innerHTML = modalHtml;
    document.body.appendChild(container);

    document.getElementById('closeSurveyModalBtn').addEventListener('click', function() {
      container.remove();
      form.reset();
      window.scrollTo({ top: 0, behavior: 'smooth' });
    });
  });
})();

