      "Tôi hành động mà chẳng cần phí thời gian cho việc thu thập thông tin.",
      "Tôi cố gắng suy nghĩ về tất cả các vấn đề tôi có thể sẽ gặp phải và lên kế hoạch phải làm gì nếu quả thực các vấn đề đó xảy ra.",
      "Tôi nhờ những người quan trọng giúp đỡ để hoàn thành các mục tiêu của tôi.",
      "Trong khi thử làm một việc gì đó khó khăn, tôi tin tưởng rằng tôi sẽ thành công.",
      "Trong quá khứ tôi đã từng thất bại.",
      "Tôi thích những công việc mà tôi biết rõ và cảm thấy thoải mái.",
      "Khi đối mặt với những khó khăn chủ yếu tôi nhanh chóng chuyển sang làm các công việc khác.",
      "Khi tôi làm việc cho một ai đó, tôi đặc biệt cố gắng để người đó hài lòng về công việc của tôi.",
      "Tôi không khi nào hoàn toàn bằng lòng với những cách làm việc đã có, tôi luôn nghĩ rằng còn có thể có cách khác tốt hơn.",
      "Tôi làm những việc phiêu lưu mạo hiểm.",
      "Tôi có kế hoạch rất rõ ràng cho cuộc đời của tôi.",
      "Khi tôi thực hiện một dự án cho ai đó, tôi đặt ra rất nhiều câu hỏi để có thể chắc chắn rằng tôi đã hiểu đúng những gì người đó muốn.",
      "Tôi giải quyết các vấn đề khi chúng đã nảy sinh, chứ không chịu mất thời gian để dự đoán những vấn đề này.",
      "Để đạt được mục đích của tôi, tôi suy nghĩ về các giải pháp mang lại lợi ích cho tất cả những ai tham gia vào công việc này.",
      "Tôi làm công việc rất tốt.",
      "Đã từng có trường hợp tôi lừa dối ai đó.",
      "Tôi thử làm những việc hoàn toàn mới và khác lạ đối với những gì tôi đã làm trước đây.",
      "Tôi thử rất nhiều cách để khắc phục những cản trở việc đạt được mục đích của tôi.",
      "Gia đình và cuộc sống riêng tư có tầm quan trọng đối với tôi hơn là các thời hạn mà tôi đã đặt ra cho mình.",
      "Tôi không tìm được các cách thức để có thể hoàn thành nhiệm vụ nhanh hơn cả ở cơ quan lẫn ở nhà.",
      "Tôi làm những công việc mà người khác cho là mạo hiểm.",
      "Tôi lo lắng cho việc hoàn thành các mục tiêu trong tuần chẳng kém gì lo lắng cho các mục tiêu trong cả năm.",
      "Tôi tìm kiếm thông tin từ nhiều nguồn khác nhau để giải quyết các nhiệm vụ hay thực hiện các dự án của mình.",
      "Nếu cách tiếp cận vấn đề này không thành công thì tôi suy nghĩ tìm cách tiếp cận khác.",
      "Tôi có khả năng làm cho những người có quan điểm hoặc ý tưởng vững chắc phải thay đổi ý kiến.",
      "Tôi giữ vững các quyết định của mình kể cả trong trường hợp những người khác bất đồng với tôi.",
      "Khi tôi không biết điều gì đó, tôi công nhận là tôi không biết."
    ];

    const pecDefs = [
      { name: "Tìm kiếm cơ hội", formula: [[1, +1], [12, +1], [23, +1], [34, -1], [45, +1]], base: 6 },
      { name: "Kiên định", formula: [[2, +1], [13, +1], [24, +1], [35, -1], [46, +1]], base: 6 },
      { name: "Gắn bó với công việc", formula: [[3, +1], [14, +1], [25, +1], [36, +1], [47, -1]], base: 6 },
      { name: "Đòi hỏi chất lượng & hiệu quả", formula: [[4, +1], [15, +1], [26, +1], [37, +1], [48, -1]], base: 6 },
      { name: "Chịu mạo hiểm", formula: [[5, +1], [16, -1], [27, +1], [38, +1], [49, +1]], base: 6 },
      { name: "Có mục đích rõ ràng", formula: [[6, +1], [17, -1], [28, +1], [39, +1], [50, +1]], base: 6 },
      { name: "Chịu thu thập thông tin", formula: [[7, +1], [18, +1], [29, -1], [40, +1], [51, +1]], base: 6 },
      { name: "Lập kế hoạch & QL hệ thống", formula: [[8, +1], [19, +1], [30, +1], [41, -1], [52, +1]], base: 6 },
      { name: "Thuyết phục & gây quan hệ", formula: [[9, +1], [20, -1], [31, +1], [42, +1], [53, +1]], base: 6 },
      { name: "Tự tin", formula: [[10, +1], [21, -1], [32, +1], [43, +1], [54, +1]], base: 6 }
    ];

    const adjItems = [11, 22, 33, 44, 55];

    const qBody = document.getElementById('qBody');
    const pgBar = document.getElementById('pg');
    const pgText = document.getElementById('pgText');
    const pecBody = document.getElementById('pecBody');
    const answeredEl = document.getElementById('answered');
    const answeredPill = document.getElementById('answeredPill');
    const adjFactorEl = document.getElementById('adjFactor');
    const adjHint = document.getElementById('adjHint');
    const completeHint = document.getElementById('completeHint');
    const sumRawEl = document.getElementById('sumRaw');
    const sumAdjEl = document.getElementById('sumAdj');

    // Dựng 55 câu trắc nghiệm
    questions.forEach((text, idx) => {
      const n = idx + 1;
      const tr = document.createElement('tr');
      tr.className = "hover:bg-slate-50/70 transition-colors";
      tr.innerHTML = `
        <td class="text-center font-bold text-slate-500 border-r border-slate-200 num-font">${n}</td>
        <td class="border-r border-slate-200 leading-snug py-1.5 px-2">${text}</td>
        <td class="text-center py-1 px-1.5">
          <select id="q${n}" aria-label="Câu ${n}" data-index="${n}" class="w-full bg-white border border-slate-300 rounded px-1.5 py-1 text-[10px] num-font focus:outline-none focus:border-[#E8DDE0]">
            <option value="">—</option>
            <option value="5">5 — Luôn luôn</option>
            <option value="4">4 — Thường xuyên</option>
            <option value="3">3 — Đôi khi</option>
            <option value="2">2 — Hiếm khi</option>
            <option value="1">1 — Không bao giờ</option>
          </select>
        </td>`;
      qBody.appendChild(tr);
    });

    // Dựng 10 dòng bảng PEC
    pecDefs.forEach((pec, i) => {
      const idx = i + 1;
      const fTxt = pec.formula.map(([q, sgn]) => `${sgn > 0 ? '+' : '−'} (${q})`).join(' ').replace(/^\+ /, '');
      const tr = document.createElement('tr');
      tr.className = "hover:bg-slate-50/70 transition-colors";
      tr.innerHTML = `
        <td class="border-r border-slate-200 font-bold num-font text-[#A83245]">PEC ${idx}</td>
        <td class="border-r border-slate-200 text-left font-medium">${pec.name}</td>
        <td class="border-r border-slate-200 num-font text-[9px] text-slate-500">${fTxt} + ${pec.base}</td>
        <td class="border-r border-slate-200 num-font font-bold" id="raw${idx}">—</td>
        <td class="border-r border-slate-200 num-font" id="delta${idx}">—</td>
        <td class="num-font font-extrabold text-[#A83245]" id="final${idx}">—</td>`;
      pecBody.appendChild(tr);
    });

    function getVal(n) {
      const v = document.getElementById('q' + n).value;
      return v === '' ? NaN : Number(v);
    }

    function adjDelta(total) {
      if (total >= 24) return -7;
      if (total >= 22) return -5;
      if (total >= 20) return -3;
      return 0;
    }

    function countAnswered() {
      let ans = 0;
      for (let i = 1; i <= 55; i++) {
        if (!Number.isNaN(getVal(i))) ans++;
      }
      return ans;
    }

    function updateProgress() {
      const ans = countAnswered();
      const pct = Math.round(ans / 55 * 100);
      pgBar.style.width = pct + '%';
      pgText.textContent = pct + "% hoàn thành";
    }

    function recalc() {
      let ans = countAnswered();
      answeredEl.textContent = ans + "/55";
      answeredPill.textContent = ans + "/55 câu";
      updateProgress();

      let af = 0;
      let afComplete = true;
      adjItems.forEach(n => {
        const v = getVal(n);
        if (Number.isNaN(v)) afComplete = false;
        else af += v;
      });

      adjFactorEl.textContent = afComplete ? af : '—';

      if (afComplete) {
        const d = adjDelta(af);
        adjHint.classList.remove('hidden');
        adjHint.textContent = d === 0 
          ? `Điểm hiệu chỉnh kiểm soát = ${af} → Đạt độ tin cậy chuẩn, không trừ điểm PEC.`
          : `Điểm hiệu chỉnh kiểm soát = ${af} → Phát hiện xu hướng trả lời quá lý tưởng hóa, mỗi chỉ số PEC được điều chỉnh ${d} điểm.`;
      } else {
        adjHint.classList.add('hidden');
      }

      if (ans === 55) {
        completeHint.classList.remove('hidden');
      } else {
        completeHint.classList.add('hidden');
      }

      let sumRaw = 0, sumFinal = 0;
      pecDefs.forEach((pec, i) => {
        let ok = true;
        let s = 0;
        pec.formula.forEach(([q, sgn]) => {
          const v = getVal(q);
          if (Number.isNaN(v)) ok = false;
          else s += sgn * v;
        });

        const raw = ok ? s + pec.base : NaN;
        document.getElementById('raw' + (i + 1)).textContent = ok ? raw : '—';

        let delta = '—', final = '—';
        if (ok && afComplete) {
          const d = adjDelta(af);
          delta = d;
          final = raw + d;
          sumRaw += raw;
          sumFinal += final;
        }
        document.getElementById('delta' + (i + 1)).textContent = delta;
        document.getElementById('final' + (i + 1)).textContent = final;
      });

      sumRawEl.textContent = (ans === 55 && afComplete) ? sumRaw : '—';
      sumAdjEl.textContent = (ans === 55 && afComplete) ? sumFinal : '—';

      try {
        window.__runAutoAnalysis && window.__runAutoAnalysis();
      } catch (e) {}
    }

    document.getElementById('btnRecalc').addEventListener('click', recalc);
    document.getElementById('btnClear').addEventListener('click', () => {
      if (!confirm('Bạn có chắc chắn muốn xóa toàn bộ câu trả lời đã điền?')) return;
      for (let i = 1; i <= 55; i++) {
        const el = document.getElementById('q' + i);
        if (el) el.value = '';
      }
      recalc();
    });

    document.getElementById('qBody').addEventListener('change', recalc, true);

    qBody.addEventListener('keydown', (e) => {
      const k = e.key;
      if (['1', '2', '3', '4', '5'].includes(k)) {
        const sel = e.target.closest('select');
        if (sel) {
          sel.value = k;
          sel.dispatchEvent(new Event('change', { bubbles: true }));
        }
      }
    });

    // =========================================================================
    // LOGIC PHÂN TÍCH TỰ ĐỘNG & BIỂU ĐỒ CHART.JS
    // =========================================================================
    const FACTORS = [
      "Tìm kiếm cơ hội", "Kiên định", "Gắn bó với công việc",
      "Đòi hỏi chất lượng", "Dám mạo hiểm",
      "Mục đích rõ ràng", "Thu thập thông tin",
      "Lập KH hệ thống", "Thuyết phục", "Tự tin"
    ];

    const GROUPS = {
      "Định hướng mục tiêu & kiên trì": ["Kiên định", "Mục đích rõ ràng", "Gắn bó với công việc"],
      "Sáng tạo & cơ hội": ["Tìm kiếm cơ hội", "Dám mạo hiểm", "Thu thập thông tin"],
      "Quản lý & tổ chức": ["Đòi hỏi chất lượng", "Lập KH hệ thống"],
      "Xã hội & lãnh đạo": ["Thuyết phục", "Tự tin"]
    };

    function readFinalScores() {
      const scores = [];
      for (let i = 1; i <= 10; i++) {
        const cell = document.getElementById('final' + i);
        if (!cell) return null;
        const val = cell.textContent.trim();
        if (val === '—' || val === '') return null;
        const num = Number(val);
        if (Number.isNaN(num)) return null;
        scores.push(num);
      }
      return scores;
    }

    function buildFeedback(scores) {
      let strengths = [], weaknesses = [];
      scores.forEach((s, i) => {
        if (s >= 20) strengths.push(FACTORS[i]);
        else if (s <= 16) weaknesses.push(FACTORS[i]);
      });

      let html = "<div><strong>Đặc trưng thế mạnh nổi trội:</strong> ";
      html += strengths.length
        ? "Bạn đạt điểm rất cao ở các nhóm năng lực: <span class='text-emerald-700 font-bold'>" + strengths.join(", ") + "</span>."
        : "<span class='text-slate-500 italic'>Chưa có chỉ số nào thực sự vượt trội (&ge; 20 điểm), cần rèn luyện thêm.</span>";
      html += "</div>";

      html += "<div><strong>Khu vực cần tập trung cải thiện:</strong> ";
      html += weaknesses.length
        ? "Nên ưu tiên củng cố các kỹ năng: <span class='text-amber-800 font-bold'>" + weaknesses.join(", ") + "</span> để cân đối hồ sơ năng lực khởi nghiệp."
        : "<span class='text-emerald-700 font-semibold'>Các chỉ số đều duy trì ở mức cân bằng và ổn định.</span>";
      html += "</div>";

      html += "<div class='pt-1.5 border-t border-slate-200'><strong>Đánh giá tổng quan theo cụm năng lực:</strong><ul class='list-disc list-inside pl-1 space-y-0.5 pt-0.5'>";
      for (let [groupName, items] of Object.entries(GROUPS)) {
        const groupScores = items.map(item => scores[FACTORS.indexOf(item)]);
        const avg = groupScores.reduce((a, b) => a + b, 0) / groupScores.length;
        if (avg >= 20) {
          html += `<li><b>${groupName}</b>: <span class='text-emerald-700 font-bold'>Rất mạnh (${avg.toFixed(1)}/25)</span> — Thể hiện phong cách quyết đoán và chủ động.</li>`;
        } else if (avg <= 16) {
          html += `<li><b>${groupName}</b>: <span class='text-rose-700 font-bold'>Cần cải thiện (${avg.toFixed(1)}/25)</span> — Cần bồi dưỡng thêm qua thực tế dự án.</li>`;
        } else {
          html += `<li><b>${groupName}</b>: <span class='text-[#A83245] font-semibold'>Mức khá (${avg.toFixed(1)}/25)</span> — Đã có nền tảng, cần tiếp tục phát huy.</li>`;
        }
      }
      html += "</ul></div>";
      return html;
    }

    let chart;
    function renderChart(scores) {
      const ctx = document.getElementById('pecChart').getContext('2d');
      if (chart) { chart.destroy(); }
      chart = new Chart(ctx, {
        type: 'bar',
        data: {
          labels: FACTORS,
          datasets: [{
            label: 'Điểm PEC cuối cùng',
            data: scores,
            backgroundColor: scores.map(s => s >= 20 ? 'rgba(16, 185, 129, 0.7)' : (s <= 16 ? 'rgba(245, 158, 11, 0.7)' : 'rgba(2, 132, 199, 0.7)')),
            borderColor: scores.map(s => s >= 20 ? '#059669' : (s <= 16 ? '#d97706' : '#0284c7')),
            borderWidth: 1.5,
            borderRadius: 4
          }]
        },
        options: {
          indexAxis: 'y',
          responsive: true,
          maintainAspectRatio: false,
          scales: {
            x: {
              beginAtZero: true,
              max: 25,
              ticks: { font: { family: 'Roboto Mono', size: 10 } },
              title: { display: true, text: 'Thang điểm (0 – 25)', font: { size: 10, weight: 'bold' } }
            },
            y: {
              ticks: { font: { family: 'Inter', size: 10 } }
            }
          },
          plugins: {
            legend: { display: false }
          }
        }
      });
    }

    function runAnalysis() {
      const scores = readFinalScores();
      const fb = document.getElementById('feedback');
      if (!scores) {
        fb.innerHTML = "<p class='text-slate-500 italic'>⚠️ Chưa có đủ dữ liệu để phân tích. Hãy hoàn thành trọn vẹn 55 câu hỏi và nhấn nút <strong>'Tính lại'</strong>.</p>";
        return;
      }
      fb.innerHTML = buildFeedback(scores);
      renderChart(scores);
    }

    document.getElementById('btnAnalyze').addEventListener('click', runAnalysis);

    const pecBodyNode = document.getElementById('pecBody');
    if (window.MutationObserver && pecBodyNode) {
      const obs = new MutationObserver(() => runAnalysis());
      obs.observe(pecBodyNode, { childList: true, subtree: true, characterData: true });
    }
    window.__runAutoAnalysis = runAnalysis;

    document.addEventListener('DOMContentLoaded', () => {
      recalc();
      runAnalysis();
    });

