:root, .tkd-page-scope {
    --bg:#fafafa; --ink:#1f2937; --muted:#6b7280; --accent:#2563eb; --line:#e5e7eb;
    --card:#ffffff; --shadow:0 6px 20px rgba(0,0,0,.06); --radius:16px;
    --note:#f9fafb; --quote:#fff7ed;
  }

  .tkd-page-scope *, .tkd-page-scope *::before, .tkd-page-scope *::after {box-sizing:border-box}

  .tkd-page-scope, .tkd-page-scope {margin:0;background:var(--bg);color:var(--ink);font-family:'Segoe UI',Roboto,Inter,Arial,sans-serif;line-height:1.7}

  .tkd-page-scope .wrap {max-width:920px;margin:28px auto;padding:0 18px 48px}

  .tkd-page-scope header {text-align:center;margin-bottom:28px}

  .tkd-page-scope .title {margin:.2rem 0 .5rem;font-size:clamp(24px,3.2vw,34px);font-weight:800;color:#111827}

