// 1. Cập nhật năm tự động
    document.addEventListener("DOMContentLoaded", function() {
      const year = new Date().getFullYear();
      const currentYearEl = document.getElementById("currentYear");
      const footerYearEl = document.getElementById("footerYear");
      if (currentYearEl) currentYearEl.textContent = year;
      if (footerYearEl) footerYearEl.textContent = year;
      
    });

    // 2. Logic xử lý tạo tên đề tài và phân loại chuyên sâu (Đã tích hợp đầy đủ danh mục Quản trị Kinh doanh & Marketing chuẩn)
    document.getElementById('suggestionForm').addEventListener('submit', function(event) {
      event.preventDefault();

      const field = document.getElementById('field').value.trim();
      const company = document.getElementById('company').value.trim();

      function formatCompany(str) {
        if (!str) return '';
        return str.trim();
      }

      const formattedCompany = formatCompany(company);
      const currentYear = new Date().getFullYear();
      const futureYear = currentYear + 3;

      // Đề tài chính
      const mainTitle = `Một số giải pháp hoàn thiện hoạt động ${field} tại ${formattedCompany} giai đoạn từ năm ${currentYear} đến năm ${futureYear}.`;
      
      const resultBox = document.getElementById('resultBox');
      const mainSuggestion = document.getElementById('mainSuggestion');
      mainSuggestion.textContent = mainTitle;
      resultBox.classList.remove('hidden');

      // Danh mục đề tài mở rộng theo từ khóa chuyên ngành Quản trị Kinh doanh & Marketing
      const fieldLower = field.toLowerCase();
      let suggestions = [];

      if (fieldLower.match(/marketing|bán hàng|quảng cáo|phân phối|sản phẩm|chiêu thị|định giá|thương hiệu|nhãn hàng/)) {
        suggestions = [
          `Thực trạng và một số giải pháp hoàn thiện chiến lược Marketing – mix tại ${formattedCompany}.`,
          `Nghiên cứu thị trường cho sản phẩm của ${formattedCompany}.`,
          `Một số giải pháp mở rộng thị trường tại ${formattedCompany}.`,
          `Một số giải pháp nâng cao năng lực cạnh tranh của ${formattedCompany}.`,
          `Một số giải pháp nâng cao hiệu quả hoạt động tiêu thụ sản phẩm tại ${formattedCompany}.`,
          `Quản trị chất lượng sản phẩm tại ${formattedCompany}.`,
          `Xây dựng chiến lược sản phẩm (giá, phân phối, chiêu thị cổ động) tại ${formattedCompany}.`,
          `Hoàn thiện mạng lưới kênh phân phối tại ${formattedCompany}.`,
          `Một số giải pháp hoàn thiện công tác quản lý mạng lưới nhân viên bán hàng của ${formattedCompany}.`,
          `Giải pháp xây dựng và phát triển thương hiệu tại ${formattedCompany}.`,
          `Phân tích và đánh giá hiệu quả hoạt động Content Marketing tại ${formattedCompany}.`,
          `Xây dựng kế hoạch nội dung mạng xã hội (Facebook, Instagram, TikTok…) cho sản phẩm hoặc dịch vụ tại ${formattedCompany}.`,
          `Đánh giá hiệu quả chiến dịch Facebook Ads hoặc Google Ads tại ${formattedCompany}.`
        ];
      } else if (fieldLower.match(/kinh doanh|tài chính|hoạt động kinh doanh|doanh thu|vốn|lợi nhuận/)) {
        suggestions = [
          `Phân tích tình hình hoạt động kinh doanh của ${formattedCompany}.`,
          `Phân tích tình hình tài chính của ${formattedCompany}.`,
          `Phân tích tình hình sử dụng vốn tại ${formattedCompany}.`,
          `Lợi nhuận và giải pháp gia tăng lợi nhuận tại ${formattedCompany}.`,
          `Doanh thu bán hàng và giải pháp gia tăng doanh thu bán hàng tại ${formattedCompany}.`,
          `Giải pháp nâng cao hiệu quả công tác huy động và sử dụng vốn tại ${formattedCompany}.`
        ];
      } else if (fieldLower.match(/nhân sự|nhân lực|tiền lương|thưởng|tuyển dụng|đào tạo|đãi ngộ|động viên|lao động/)) {
        suggestions = [
          `Thực trạng và một số giải pháp hoàn thiện bộ máy tổ chức quản lý, tổ chức nhân sự của ${formattedCompany}.`,
          `Phân tích tình hình sử dụng lao động tại ${formattedCompany}.`,
          `Hoàn thiện công tác quản lý và sử dụng quỹ tiền lương, tiền thưởng tại ${formattedCompany}.`,
          `Xây dựng định mức lao động và xác định đơn giá tiền lương cho sản phẩm tại ${formattedCompany}.`,
          `Nâng cao hiệu quả công tác tuyển dụng tại ${formattedCompany}.`,
          `Nâng cao hiệu quả công tác phát triển nguồn nhân lực tại ${formattedCompany}.`,
          `Nâng cao hiệu quả công tác động viên nhân viên tại ${formattedCompany}.`
        ];
      } else if (fieldLower.match(/sản xuất|kho hàng|nguyên liệu|cung ứng/)) {
        suggestions = [
