          `Hoạch định nhu cầu nguyên liệu tại ${formattedCompany}.`
        ];
      } else if (fieldLower.match(/chiến lược/)) {
        suggestions = [
          `Thực trạng và một số giải pháp hoàn thiện chiến lược kinh doanh của ${formattedCompany}.`,
          `Phân tích môi trường kinh doanh của ${formattedCompany}, phân tích điểm mạnh, điểm yếu, cơ hội – nguy cơ để đề ra giải pháp hoàn thiện chiến lược.`,
          `Phân tích, đánh giá ưu nhược điểm của các chiến lược kinh doanh hiện tại của ${formattedCompany}.`,
          `Hoàn thiện công tác hoạch định chiến lược của ${formattedCompany}.`,
          `Xây dựng chiến lược kinh doanh cho ${formattedCompany}.`
        ];
      } else if (fieldLower.match(/chất lượng/)) {
        suggestions = [
          `Nhận xét, đánh giá về thực trạng hoạt động quản trị chất lượng tại ${formattedCompany}.`,
          `Đánh giá thực trạng thực hiện quy trình đảm bảo chất lượng trong ${formattedCompany}.`,
          `Nhận xét, đánh giá về các tiêu chuẩn chất lượng mà ${formattedCompany} đang áp dụng.`
        ];
      } else {
        suggestions = [
          `Một số giải pháp hoàn thiện hoạt động ${field} tại ${formattedCompany} giai đoạn ${currentYear} – ${futureYear}.`,
          `Một số giải pháp nâng cao chất lượng và hiệu quả hoạt động ${field} tại ${formattedCompany} giai đoạn ${currentYear} – ${futureYear}.`,
