site_pages.custom_js:
document.addEventListener("DOMContentLoaded", function() {
      // 1. Tự động tính toán và cập nhật các mốc năm theo quy tắc:
      // Năm đề tài & Chương 3: Năm hiện tại -> Năm hiện tại + 3 năm
      // Năm Chương 2 (Thực trạng): Năm hiện tại - 3 năm -> Năm hiện tại
      const currentYear = new Date().getFullYear();
      const pastStartYear = currentYear - 3;
      const futureEndYear = currentYear + 3;

      const futureRangeText = `${currentYear} – ${futureEndYear}`;
      const pastRangeText = `${pastStartYear} – ${currentYear}`;
      const futureWordsText = `${currentYear} đến năm ${futureEndYear}`;
      const pastWordsText = `${pastStartYear} đến năm ${currentYear}`;

      // Cập nhật tất cả các vị trí thời gian tương lai (dạng dấu gạch nối)
      document.querySelectorAll('.range-future').forEach(function(el) {
        el.textContent = futureRangeText;
      });

      // Cập nhật tất cả các vị trí thời gian quá khứ (dạng dấu gạch nối)
      document.querySelectorAll('.range-past').forEach(function(el) {
        el.textContent = pastRangeText;
      });

      // Cập nhật các vị trí dùng chữ "từ năm ... đến năm ..."
      document.querySelectorAll('.range-future-words').forEach(function(el) {
        el.textContent = futureWordsText;
      });

      document.querySelectorAll('.range-past-words').forEach(function(el) {
        el.textContent = pastWordsText;
      });

      // Cập nhật chân trang
      const footerYear = document.getElementById("footerYear");
      if (footerYear) footerYear.textContent = currentYear;

      // 2. Chuyển đổi qua lại giữa 5 Tab Đề tài
      const tabButtons = document.querySelectorAll(".tab-btn");
      const contentSections = document.querySelectorAll(".content-section");

      tabButtons.forEach(function(btn) {
        btn.addEventListener("click", function(e) {
          e.preventDefault();
          const targetId = this.getAttribute("data-target");

          tabButtons.forEach(function(b) {
            b.classList.remove("active");
          });
          this.classList.add("active");

          contentSections.forEach(function(section) {
            if (section.id === targetId) {
              section.classList.remove("hidden");
            } else {
              section.classList.add("hidden");
            }
          });
          window.scrollTo({ top: 0, behavior: 'smooth' });
        });
      });

      // 3. Thanh cuộn tiến độ đọc
      const progressBar = document.getElementById("progressBar");
      window.addEventListener("scroll", function() {
        const scrollTop = document.documentElement.scrollTop || document.body.scrollTop;
        const scrollHeight = document.documentElement.scrollHeight - document.documentElement.clientHeight;
        if (scrollHeight > 0 && progressBar) {
          const progress = (scrollTop / scrollHeight) * 100;
          progressBar.style.width = progress + "%";
        }
      }, { passive: true });
    });

