        { name: "Trung", birthday: "15/10" },
        { name: "Lan", birthday: "20/11" },
        { name: "Nam", birthday: "05/01" }
      ];

      const today = new Date();
      const currentDay = today.getDate();
      const currentMonth = today.getMonth() + 1;
      const greetingBar = document.getElementById("greetingBar");
      let birthdayPerson = null;

      for (const person of birthdayList) {
        const [day, month] = person.birthday.split("/").map(Number);
        if (day === currentDay && month === currentMonth) {
          birthdayPerson = person.name;
          break;
        }
      }

      if (birthdayPerson) {
        greetingBar.className = "inline-flex items-center gap-1.5 px-3.5 py-1 rounded-full text-xs font-semibold bg-rose-500/20 text-rose-200 border border-rose-400/40 backdrop-blur-xs shadow-2xs animate-pulse";
        greetingBar.innerHTML = `🎁 Chúc mừng sinh nhật bạn <strong>${birthdayPerson}</strong>! Chúc bạn tuổi mới nhiều thành công và năng lượng mới! 🎂`;
      } else {
        greetingBar.className = "inline-flex items-center gap-1.5 px-3.5 py-1 rounded-full text-xs font-semibold bg-[#A83245]/60 text-amber-300 border border-[#E8DDE0]/30 backdrop-blur-xs shadow-2xs";
        greetingBar.innerHTML = `☀️ Chúc các bạn sinh viên một ngày học tập và rèn luyện tràn đầy hứng khởi và năng lượng!`;
      }
    });

    // 2. Logic Máy tính khoảng điểm thi
    const hs1 = document.getElementById('hs1');
    const hs2 = document.getElementById('hs2');
    const btnCalc = document.getElementById('calc');
    const btnReset = document.getElementById('reset');
    const tb40 = document.getElementById('tb40');
    const tbody = document.getElementById('tbody');
    const roundSel = document.getElementById('round');

    const grades = [
      { key: 'A', min: 8.5, max: 10.0, badgeBg: 'bg-emerald-100 text-emerald-800 border border-emerald-300' },
      { key: 'B', min: 7.0, max: 8.4, badgeBg: 'bg-[#A83245] text-[#A83245] border border-[#E8DDE0]' },
      { key: 'C', min: 5.5, max: 6.9, badgeBg: 'bg-amber-100 text-amber-800 border border-amber-300' },
      { key: 'D', min: 4.0, max: 5.4, badgeBg: 'bg-orange-100 text-orange-800 border border-orange-300' },
      { key: 'F', min: 0.0, max: 3.9, badgeBg: 'bg-rose-100 text-rose-800 border border-rose-300' },
    ];

    function fmt(x, digits) {
      return Number.isFinite(x) ? x.toFixed(digits) : '–';
    }

    function compute() {
      const v1 = parseFloat(hs1.value);
      const v2 = parseFloat(hs2.value);
      const digits = parseInt(roundSel.value, 10);

      if (!Number.isFinite(v1) || !Number.isFinite(v2) || v1 < 0 || v1 > 10 || v2 < 0 || v2 > 10) {
        tbody.innerHTML = `<tr><td colspan="4" class="py-2 text-rose-600 font-bold text-[9.5px]">⚠️ Vui lòng nhập điểm HS1 và HS2 hợp lệ từ 0 đến 10.</td></tr>`;
        tb40.textContent = '–';
        return;
      }

      const avg = (v1 + 2 * v2) / 3;
      const part40 = avg * 0.4;
      tb40.textContent = fmt(part40, digits);

      const rows = grades.map(g => {
        let thiMin = (g.min - part40) / 0.6;
        let thiMax = (g.max - part40) / 0.6;

        if (g.key !== 'F') {
          thiMin = Math.max(2, thiMin); // Quy chế điểm liệt kết thúc học phần
        }

        thiMin = Math.max(0, thiMin);
        thiMax = Math.min(10, thiMax);

        const possible = thiMin <= thiMax && thiMin <= 10 && thiMax >= 0;

        if (!possible) {
          return `
            <tr>
              <td class="border-r border-slate-200"><span class="px-1.5 py-0.5 rounded text-[8.5px] font-bold ${g.badgeBg}">${g.key}</span></td>
              <td class="border-r border-slate-200 num-font">${g.min} – ${g.max}</td>
              <td class="border-r border-slate-200 font-sans italic text-slate-400">Không thể đạt</td>
              <td class="text-rose-600 font-sans font-medium text-[8px] sm:text-[9.5px]">Điểm quá trình không cho phép</td>
            </tr>
          `;
        }

        return `
          <tr class="hover:bg-slate-50/70">
            <td class="border-r border-slate-200"><span class="px-1.5 py-0.5 rounded text-[8.5px] font-bold ${g.badgeBg}">${g.key}</span></td>
            <td class="border-r border-slate-200 num-font">${g.min} – ${g.max}</td>
            <td class="border-r border-slate-200 num-font font-bold text-[#A83245]">${fmt(thiMin, digits)} – ${fmt(thiMax, digits)}</td>
            <td class="text-emerald-700 font-semibold font-sans">Khả thi</td>
          </tr>
        `;
      }).join('');

      tbody.innerHTML = rows;
    }

    btnCalc.addEventListener('click', compute);
    btnReset.addEventListener('click', () => {
      hs1.value = '';
      hs2.value = '';
      tb40.textContent = '–';
      tbody.innerHTML = '<tr><td colspan="4" class="py-4 text-center text-slate-400 italic font-sans">Nhập điểm HS1, HS2 rồi nhấn "Tính điểm cần" để xem kết quả.</td></tr>';
    });

    // 3. Logic Máy tính cải thiện GPA
    function addImprovementSubject() {
      const subjectList = document.getElementById("improvementSubjectList");
      const newSubject = document.createElement("div");
      newSubject.className = "improvement-subject bg-[#A83245]/50 p-2 rounded-lg border border-[#E8DDE0] grid grid-cols-12 gap-1.5 items-end";
      newSubject.innerHTML = `
        <div class="col-span-3">
          <label class="block text-[8.5px] sm:text-[9.5px] font-semibold text-slate-700">Số TC:</label>
          <input type="number" class="subjectCredits w-full bg-white border border-slate-300 rounded px-1.5 py-0.5 text-[10.5px] num-font" min="1" value="3" />
        </div>
        <div class="col-span-4">
          <label class="block text-[8.5px] sm:text-[9.5px] font-semibold text-slate-700">Điểm cũ (0-10):</label>
          <input type="number" class="oldScore w-full bg-white border border-slate-300 rounded px-1.5 py-0.5 text-[10.5px] num-font" step="0.1" min="0" max="10" placeholder="Điểm cũ" />
        </div>
        <div class="col-span-4">
          <label class="block text-[8.5px] sm:text-[9.5px] font-semibold text-slate-700">Điểm mới kỳ vọng:</label>
          <input type="number" class="newScore w-full bg-white border border-slate-300 rounded px-1.5 py-0.5 text-[10.5px] num-font" step="0.1" min="0" max="10" placeholder="Điểm mới" />
        </div>
        <div class="col-span-1 text-center">
          <button type="button" onclick="removeSubject(this)" class="text-red-500 hover:text-red-700 font-bold text-xs" title="Xóa môn">✕</button>
        </div>
      `;
      subjectList.appendChild(newSubject);
    }

    function removeSubject(button) {
      button.closest(".improvement-subject").remove();
    }

    function calculateCreditsToRetake() {
      const currentScore = parseFloat(document.getElementById("currentScore").value);
      const totalCredits = parseInt(document.getElementById("totalCredits").value);
      const desiredGPA = parseFloat(document.getElementById("desiredGPA").value);
      const resultDiv = document.getElementById("result");

      resultDiv.classList.remove("hidden");

      if (isNaN(currentScore) || isNaN(totalCredits) || isNaN(desiredGPA) || totalCredits <= 0 || desiredGPA < 0 || desiredGPA > 4 || currentScore < 0 || currentScore > 10) {
        resultDiv.className = "bg-rose-50 border-l-3 border-rose-600 p-2.5 rounded-r-lg text-[10px] sm:text-xs text-rose-900";
        resultDiv.innerHTML = "<strong>⚠️ Thông báo:</strong> Vui lòng nhập đầy đủ và chính xác các thông tin cơ bản: Điểm trung bình (0–10), Tổng tín chỉ (&gt;0) và GPA mục tiêu (0–4).";
        return;
      }

      const currentGPA = (currentScore / 10) * 4;
      const improvementSubjects = document.querySelectorAll(".improvement-subject");
      let improvementPoints = 0;
      let improvementCredits = 0;

      for (const subject of improvementSubjects) {
        const credits = parseInt(subject.querySelector(".subjectCredits").value);
        const oldScore = parseFloat(subject.querySelector(".oldScore").value);
        const newScore = parseFloat(subject.querySelector(".newScore").value);

        if (isNaN(credits) || isNaN(oldScore) || isNaN(newScore) || credits <= 0 || oldScore < 0 || oldScore > 10 || newScore < 0 || newScore > 10) {
          resultDiv.className = "bg-rose-50 border-l-3 border-rose-600 p-2.5 rounded-r-lg text-[10px] sm:text-xs text-rose-900";
          resultDiv.innerHTML = "<strong>⚠️ Thông báo:</strong> Vui lòng kiểm tra lại thông tin các môn cải thiện (Số tín chỉ &gt; 0, Điểm số từ 0 đến 10).";
          return;
        }

        const oldGPA = (oldScore / 10) * 4;
        const newGPA = (newScore / 10) * 4;
        improvementPoints += (newGPA - oldGPA) * credits;
        improvementCredits += credits;
      }

      const totalScoreBefore = currentGPA * totalCredits;
      // Khi cải thiện, tổng số tín chỉ tích lũy của chương trình không tăng lên (thay thế điểm cũ bằng điểm mới)
      const newTotalScore = totalScoreBefore + improvementPoints;
      const calculatedGPA = newTotalScore / totalCredits;

      const isAchieved = calculatedGPA >= desiredGPA;

      if (isAchieved) {
        resultDiv.className = "bg-emerald-50 border-l-3 border-emerald-600 p-2.5 rounded-r-lg text-[10px] sm:text-xs text-emerald-950 space-y-1";
        resultDiv.innerHTML = `
          <h4 class="font-bold uppercase tracking-tight text-emerald-900">Kết Quả Mô Phỏng: Đạt Mục Tiêu 🎉</h4>
          <p>• GPA hiện tại: <strong class="num-font">${currentGPA.toFixed(2)}</strong> / 4.0</p>
          <p>• GPA dự kiến sau khi cải thiện: <strong class="num-font text-emerald-700 text-sm font-extrabold">${calculatedGPA.toFixed(2)}</strong> / 4.0</p>
          <p class="font-medium">Chúc mừng bạn! Với kết quả cải thiện này, bạn sẽ <strong>đạt hoặc vượt</strong> GPA mong muốn (<span class="num-font font-bold">${desiredGPA.toFixed(2)}</span>).</p>
        `;
      } else {
        resultDiv.className = "bg-amber-50 border-l-3 border-amber-600 p-2.5 rounded-r-lg text-[10px] sm:text-xs text-amber-950 space-y-1";
        resultDiv.innerHTML = `
          <h4 class="font-bold uppercase tracking-tight text-amber-900">Kết Quả Mô Phỏng: Chưa Đạt Mục Tiêu ⏳</h4>
          <p>• GPA hiện tại: <strong class="num-font">${currentGPA.toFixed(2)}</strong> / 4.0</p>
          <p>• GPA dự kiến sau khi cải thiện: <strong class="num-font text-amber-800 text-sm font-extrabold">${calculatedGPA.toFixed(2)}</strong> / 4.0</p>
          <p class="font-medium">Với số môn đã chọn, GPA dự kiến vẫn thấp hơn mức mong muốn (<span class="num-font font-bold">${desiredGPA.toFixed(2)}</span>). Bạn cần nâng cao mức điểm kỳ vọng hoặc đăng ký cải thiện thêm các môn có số tín chỉ lớn hơn.</p>
        `;
      }
    }

    // Logic tự động đồng bộ & lọc tin tức sinh viên từ sv.kthcm.edu.vn
    (function initHceNewsSync() {
      const container = document.getElementById('hceNewsList');
      const filterBox = document.getElementById('newsCategoryFilter');
      if (!container || !filterBox) return;

      function bindFilters() {
        const btns = filterBox.querySelectorAll('.news-filter-btn');
        const cards = container.querySelectorAll('.hce-news-card');
        btns.forEach((btn) => {
          btn.onclick = function() {
            const cat = this.getAttribute('data-category');
            btns.forEach(b => {
              b.className = 'news-filter-btn px-3 py-1.5 rounded-xl font-bold whitespace-nowrap transition-all cursor-pointer bg-white text-slate-700 hover:bg-[#A83245] border border-slate-200';
            });
            this.className = 'news-filter-btn px-3 py-1.5 rounded-xl font-bold whitespace-nowrap transition-all cursor-pointer bg-[#A83245] text-white shadow-xs';

            cards.forEach(c => {
              if (cat === 'Tất cả' || c.getAttribute('data-category') === cat) {
                c.style.display = 'flex';
              } else {
                c.style.display = 'none';
              }
            });
          };
        });
      }

      bindFilters();

      // Tự động fetch dữ liệu tin tức realtime mới nhất từ endpoint
      fetch('/api/hce-news.json')
        .then(res => res.json())
        .then(res => {
          if (!res || !res.success || !Array.isArray(res.data) || res.data.length === 0) return;
          const items = res.data;

          // Render danh sách tin mới
          container.innerHTML = items.map(n => `
            <article class="hce-news-card bg-white rounded-xl border border-slate-200 hover:border-[#E8DDE0] p-3.5 shadow-2xs hover:shadow-xs transition-all flex flex-col justify-between" data-category="${n.category || 'Thông báo'}">
              <div class="space-y-2">
                <div class="flex items-center justify-between gap-2">
                  <span class="text-[11px] font-extrabold uppercase px-2 py-0.5 rounded-md bg-[#A83245] text-[#A83245] border border-[#E8DDE0]/80">
                    ${n.category || 'Thông báo'}
                  </span>
                  <span class="text-[11px] font-semibold text-slate-500 num-font flex items-center gap-1">
                    <span>🗓️</span> ${n.date || 'Mới nhất'}
                  </span>
                </div>
                <h3 class="text-xs sm:text-sm font-bold text-slate-900 leading-snug">
                  <a href="${n.url}" target="_blank" rel="noopener noreferrer" title="Xem thông báo: ${n.title}" class="hover:text-[#A83245] transition-colors line-clamp-2">
                    ${n.title}
                  </a>
                </h3>
                ${n.summary ? `<p class="text-xs text-slate-600 leading-relaxed line-clamp-2 m-0">${n.summary}</p>` : ''}
              </div>
              <div class="pt-2.5 mt-2.5 border-t border-slate-100 flex items-center justify-between text-xs">
                <span class="text-[11px] text-slate-500 font-medium flex items-center gap-1">
                  <span>📌</span> Nguồn: <strong class="text-slate-700">${n.source || 'sv.kthcm.edu.vn'}</strong>
                </span>
                <a href="${n.url}" target="_blank" rel="noopener noreferrer" class="inline-flex items-center gap-1 font-bold text-xs text-[#A83245] hover:text-[#A83245] group">
                  <span>Xem thông báo</span>
                  <span class="group-hover:translate-x-0.5 transition-transform">↗</span>
                </a>
              </div>
            </article>
          `).join('');

          // Cập nhật lại các nút tabs nếu có category mới
          const cats = ['Tất cả', ...Array.from(new Set(items.map(x => x.category))).filter(Boolean)];
          filterBox.innerHTML = cats.map((c, i) => `
            <button type="button" data-category="${c}" class="news-filter-btn px-3 py-1.5 rounded-xl font-bold whitespace-nowrap transition-all cursor-pointer ${i === 0 ? 'bg-[#A83245] text-white shadow-xs' : 'bg-white text-slate-700 hover:bg-[#A83245] border border-slate-200'}">
              ${c}
            </button>
          `).join('');

          bindFilters();
        })
        .catch(err => {
          console.warn('[HCE News Client] Giữ danh sách tin tức tĩnh:', err);
        });
    })();

