(function() {
  const year = new Date().getFullYear();
  document.querySelectorAll('#currentYear, .js-current-year').forEach(el => {
    el.textContent = year;
  });

  const activeChapterNameEl = document.getElementById('activeChapterName');
  const btnBackToTop = document.getElementById('btnBackToTop');
  btnBackToTop?.addEventListener('click', () => {
    window.scrollTo({ top: 0, behavior: 'smooth' });
  });

  const chapters = [{"id":"chuong1","name":"Chương 1: Tổng quan về quản trị rủi ro"},{"id":"chuong2","name":"Chương 2: Nhận dạng rủi ro"},{"id":"chuong3","name":"Chương 3: Đo lường rủi ro"},{"id":"chuong4","name":"Chương 4: Kiểm soát rủi ro"},{"id":"chuong5","name":"Chương 5: Tài trợ rủi ro"}];

  if ('IntersectionObserver' in window) {
    const observer = new IntersectionObserver((entries) => {
      entries.forEach(entry => {
        if (entry.isIntersecting && activeChapterNameEl) {
          const match = chapters.find(c => c.id === entry.target.id);
          if (match) {
            activeChapterNameEl.textContent = 'Đang xem: ' + match.name;
          }
        }
      });
    }, { rootMargin: '-20% 0px -70% 0px' });

    chapters.forEach(c => {
      const el = document.getElementById(c.id);
      if (el) observer.observe(el);
    });
  }
})();

